import React, { Component } from 'react';
import DisplayGodos from './componentes/DisplayGodos';
import { GODOS } from './shared/datos';
import { Button } from 'reactstrap';

class App extends Component {
    constructor(props) {
        super(props);

        this.state = {
            godos: GODOS,
            colores: ["secondary", "secondary"],
        };
    }

    cambiarColor = (posicion) => {
        let col = ["secondary", "secondary"];

        col[posicion] = "primary";

        this.setState({
            colores: col
        });
    }

    render() {
        return (
            <div className="App">
                <header className="App-header">

                    <Button
                        color={this.state.colores[0]}
                        onClick={() => this.cambiarColor(0)}>
                        Godos
                    </Button>

                    <Button
                        color={this.state.colores[1]}
                        onClick={() => this.cambiarColor(1)}>
                        Normandos
                    </Button>

                    <DisplayGodos reyes={this.state.godos}/>

                </header>
            </div>
        );
    }
}

export default App;
